// Created in the GRETL Modeler. 😀
parameter('sourceUrl', description: 'Archive URL', type: 'text', required: false, defaultValue: 'https://example.invalid/archive.zip')
task('download', HttpDownload) {
    url = parameter('sourceUrl')
    output = workPath('archive.zip')
}
task('extract', Extract, after: 'download', dependsOn: 'download') {
    archive = result('download').file
    compression = 'ZIP'
    outputDirectory = workPath('out')
}
defaults 'extract'

// Reviewer compound G30 fixture. DO NOT SAVE DIRTY MARKER.
parameter('archiveUrl', description: 'Reviewer archive', type: 'text', required: false, defaultValue: 'https://example.invalid/reviewer.zip')
task('fetch', HttpDownload) {
    url = parameter('archiveUrl')
    output = workPath('reviewer.zip')
}
task('unpack', Extract, after: 'fetch', dependsOn: 'fetch') {
    compression = 'ZIP'
    outputDirectory = workPath('reviewer-out')
}
defaults 'unpack'
